import numpy as np


def test_emt(atoms, calculator):
    properties = ['energy', 'energies', 'free_energy', 'forces', 'stress']
    results = calculator.evaluate(atoms, properties=properties)

    ref_results = {
        'energy': -0.04778096754824723,
        'free_energy': -0.04778096754824723,
        'energies': np.array(
            [
                -0.0057312381,
                -0.0063677878,
                -0.0063400737,
                -0.0057134862,
                -0.0054304073,
                -0.006517677,
                -0.0056608759,
                -0.0060194216,
            ]
        ),
        'forces': np.array(
            [
                [0.0031997472, -0.0470866343, -0.0824298087],
                [-0.0726315518, 0.0510578802, -0.0646216023],
                [-0.0236503343, -0.0966680027, 0.0383889566],
                [-0.0075814261, 0.0377082543, 0.1069435229],
                [0.0116215799, 0.1437752208, 0.0871475393],
                [-0.0156387585, -0.049812253, -0.0006865413],
                [0.0643637267, 0.0741023073, -0.128152051],
                [0.040317017, -0.1130767726, 0.0434099845],
            ]
        ),
        'stress': np.array(
            [
                6.7692753842e-03,
                6.7653798669e-03,
                6.7528128936e-03,
                -7.4272590140e-05,
                3.1713798691e-05,
                -2.3228190719e-05,
            ]
        ),
        'natoms': 8,
    }

    for key, val in results.properties.items():
        assert np.allclose(val, ref_results[key])
